CREATE TABLE IF NOT EXISTS "growth_os"."agent_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "agent_type" "text" NOT NULL,
    "trigger_type" "text" NOT NULL,
    "source_table" "text",
    "source_id" "text",
    "lead_id" "uuid",
    "appointment_id" "uuid",
    "channel" "text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "scheduled_for" timestamp with time zone DEFAULT "now"() NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "last_error" "text",
    "idempotency_key" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "agent_jobs_agent_type_check" CHECK (("agent_type" = ANY (ARRAY['concierge'::"text", 'compliance_auditor'::"text", 'waiting_room_guardian'::"text", 'data_integrity_sync'::"text"]))),
    CONSTRAINT "agent_jobs_channel_check" CHECK (("channel" = ANY (ARRAY['whatsapp_openclaw'::"text", 'whatsapp_business_api'::"text", 'email_resend'::"text", 'email_brevo'::"text", 'admin_report'::"text"]))),
    CONSTRAINT "agent_jobs_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'reasoning'::"text", 'blocked'::"text", 'ready'::"text", 'sent'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "growth_os"."agent_jobs" OWNER TO "postgres";


COMMENT ON TABLE "growth_os"."agent_jobs" IS 'Durable queue for AI-assisted growth agents. Workers claim pending rows and record outcomes.';



CREATE OR REPLACE FUNCTION "growth_os"."claim_due_agent_jobs"("batch_size" integer DEFAULT 25) RETURNS SETOF "growth_os"."agent_jobs"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'growth_os', 'public'
    AS $$
  with due as (
    select id
    from growth_os.agent_jobs
    where status = 'pending'
      and scheduled_for <= now()
    order by scheduled_for asc, created_at asc
    limit greatest(batch_size, 1)
    for update skip locked
  )
  update growth_os.agent_jobs j
     set status = 'reasoning',
         attempts = attempts + 1,
         updated_at = now()
    from due
   where j.id = due.id
  returning j.*;
$$;


ALTER FUNCTION "growth_os"."claim_due_agent_jobs"("batch_size" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "growth_os"."topic_queue" (
    "id" bigint NOT NULL,
    "topic" "text" NOT NULL,
    "source_ref" "text",
    "target_channels" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "priority" integer DEFAULT 100 NOT NULL,
    "scheduled_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claimed_at" timestamp with time zone,
    "claimed_by" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "result_content_piece_id" "uuid",
    "attempts" integer DEFAULT 0 NOT NULL,
    "error_message" "text",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "topic_queue_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'running'::"text", 'done'::"text", 'failed'::"text", 'skipped'::"text"])))
);


ALTER TABLE "growth_os"."topic_queue" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "growth_os"."claim_next_topic"("p_claimed_by" "text") RETURNS "growth_os"."topic_queue"
    LANGUAGE "plpgsql"
    AS $$
declare
  claimed growth_os.topic_queue;
begin
  update growth_os.topic_queue
     set status      = 'running',
         claimed_at  = now(),
         claimed_by  = p_claimed_by,
         attempts    = attempts + 1,
         updated_at  = now()
   where id = (
     select id
       from growth_os.topic_queue
      where status = 'pending'
        and scheduled_at <= now()
      order by priority desc, scheduled_at asc
      for update skip locked
      limit 1
   )
   returning * into claimed;
  return claimed;
end;
$$;


ALTER FUNCTION "growth_os"."claim_next_topic"("p_claimed_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "growth_os"."dashboard_summary"("days_back" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'growth_os', 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'period_days', days_back,
    'total_leads', (SELECT count(*) FROM growth_os.leads WHERE created_at >= now() - (days_back || ' days')::interval),
    'leads_by_vertical', (
      SELECT jsonb_object_agg(vertical, cnt)
      FROM (SELECT vertical, count(*) as cnt FROM growth_os.leads WHERE created_at >= now() - (days_back || ' days')::interval GROUP BY vertical) t
    ),
    'leads_by_utm_source', (
      SELECT jsonb_object_agg(coalesce(first_utm_source, 'direct'), cnt)
      FROM (SELECT first_utm_source, count(*) as cnt FROM growth_os.leads WHERE created_at >= now() - (days_back || ' days')::interval GROUP BY first_utm_source) t
    ),
    'leads_by_day', (
      SELECT jsonb_agg(jsonb_build_object('date', d, 'count', cnt) ORDER BY d)
      FROM (SELECT date_trunc('day', created_at)::date as d, count(*) as cnt FROM growth_os.leads WHERE created_at >= now() - (days_back || ' days')::interval GROUP BY d) t
    ),
    'emails_sent', (SELECT count(*) FROM growth_os.email_jobs WHERE status = 'sent' AND sent_at >= now() - (days_back || ' days')::interval),
    'emails_by_type', (
      SELECT jsonb_object_agg(job_type, cnt)
      FROM (SELECT job_type, count(*) as cnt FROM growth_os.email_jobs WHERE status = 'sent' AND sent_at >= now() - (days_back || ' days')::interval GROUP BY job_type) t
    ),
    'conversions', (
      SELECT jsonb_build_object(
        'lead_to_appointment', count(*) FILTER (WHERE converted_to_appointment),
        'lead_to_revenue', count(*) FILTER (WHERE converted_to_revenue),
        'total_revenue', coalesce(sum(payment_amount) FILTER (WHERE converted_to_revenue), 0)
      )
      FROM growth_os.lead_attribution
      WHERE lead_created_at >= now() - (days_back || ' days')::interval
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "growth_os"."dashboard_summary"("days_back" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "growth_os"."enqueue_anamnesis_reminders"("batch_limit" integer DEFAULT 50, "min_profile_age" interval DEFAULT '02:00:00'::interval) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'growth_os', 'public'
    AS $$
declare
  v_count integer := 0;
begin
  with candidates as (
    select
      pr.user_id,
      lower(pr.email) as email,
      nullif(btrim(coalesce(pr.first_name, '')), '') as first_name,
      (
        select p.id
        from public.patients p
        where p.user_id = pr.user_id
        order by p.created_at desc nulls last
        limit 1
      ) as patient_id
    from public.profiles pr
    where pr.email is not null
      and btrim(pr.email) <> ''
      and coalesce(pr.newsletter_subscribed, true) is true
      and (pr.role is null or pr.role = 'patient')
      and coalesce(pr.created_at, now()) <= now() - min_profile_age
      and not exists (
        select 1
        from public.patients p2
        join public.anamnesis a on a.patient_id = p2.id
        where p2.user_id = pr.user_id
          and a.deleted_at is null
          and (
            a.completed_at is not null
            or a.status = 'completed'
            or coalesce(a.completion_percentage, 0) >= 100
          )
      )
      and not exists (
        select 1
        from growth_os.email_jobs ej
        where ej.dedupe_key = 'anamnesis_reminder:' || coalesce(pr.user_id::text, lower(pr.email)) || ':initial'
      )
    order by pr.created_at asc nulls last
    limit greatest(batch_limit, 0)
  )
  insert into growth_os.email_jobs (
    job_type,
    recipient_email,
    recipient_name,
    user_id,
    patient_id,
    dedupe_key,
    template_data
  )
  select
    'anamnesis_reminder',
    c.email,
    c.first_name,
    c.user_id,
    c.patient_id,
    'anamnesis_reminder:' || coalesce(c.user_id::text, c.email) || ':initial',
    jsonb_build_object(
      'action_url', 'https://www.autamedica.com/patients/anamnesis?utm_source=email&utm_medium=reminder&utm_campaign=anamnesis_activation',
      'unsubscribe_url', 'https://www.autamedica.com/unsubscribe?user=' || coalesce(c.user_id::text, c.email)
    )
  from candidates c
  on conflict (dedupe_key) do nothing;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "growth_os"."enqueue_anamnesis_reminders"("batch_limit" integer, "min_profile_age" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "growth_os"."enqueue_appointment_cancellations"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'growth_os', 'public'
    AS $$
declare
  v_doctor_profile record;
  v_patient_profile record;
  v_start text;
begin
  -- Only trigger if status changed to cancelled
  if new.status <> 'cancelled' or old.status = 'cancelled' then
    return new;
  end if;

  v_start := to_char(new.start_time at time zone 'America/Argentina/Buenos_Aires', 'DD/MM/YYYY HH24:MI');

  -- Enqueue for Doctor
  select pr.user_id, lower(pr.email) as email, nullif(btrim(coalesce(pr.first_name, '')), '') as first_name, nullif(btrim(coalesce(pr.last_name, '')), '') as last_name
  into v_doctor_profile
  from public.doctors d
  join public.profiles pr on pr.user_id = d.user_id
  where d.id = new.doctor_id
  limit 1;

  -- Enqueue for Patient
  select pr.user_id, lower(pr.email) as email, nullif(btrim(coalesce(pr.first_name, '')), '') as first_name, nullif(btrim(coalesce(pr.last_name, '')), '') as last_name
  into v_patient_profile
  from public.patients p
  join public.profiles pr on pr.user_id = p.user_id
  where p.id = new.patient_id
  limit 1;

  -- Enqueue Email to Doctor
  if v_doctor_profile.email is not null and v_doctor_profile.email <> '' then
    insert into growth_os.email_jobs (
      job_type, recipient_email, recipient_name, user_id, appointment_id, dedupe_key, template_data
    ) values (
      'doctor_appointment_cancelled',
      v_doctor_profile.email,
      v_doctor_profile.first_name,
      v_doctor_profile.user_id,
      new.id,
      'doctor_cancelled:' || new.id::text,
      jsonb_build_object(
        'appointment_time', v_start,
        'patient_name', trim(v_patient_profile.first_name || ' ' || v_patient_profile.last_name),
        'action_url', 'https://www.autamedica.com/doctors/appointments'
      )
    ) on conflict (dedupe_key) do nothing;
  end if;

  -- Enqueue Email to Patient
  if v_patient_profile.email is not null and v_patient_profile.email <> '' then
    insert into growth_os.email_jobs (
      job_type, recipient_email, recipient_name, user_id, appointment_id, dedupe_key, template_data
    ) values (
      'patient_appointment_cancelled',
      v_patient_profile.email,
      v_patient_profile.first_name,
      v_patient_profile.user_id,
      new.id,
      'patient_cancelled:' || new.id::text,
      jsonb_build_object(
        'appointment_time', v_start,
        'doctor_name', 'Dr. ' || trim(v_doctor_profile.first_name || ' ' || v_doctor_profile.last_name),
        'action_url', 'https://www.autamedica.com/patients/appointments'
      )
    ) on conflict (dedupe_key) do nothing;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "growth_os"."enqueue_appointment_cancellations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "growth_os"."enqueue_appointment_email_reminders"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'growth_os', 'public'
    AS $$
declare
  v_profile record;
  v_start text;
begin
  if new.patient_id is null or new.start_time is null then
    return new;
  end if;

  select
    pr.user_id,
    lower(pr.email) as email,
    nullif(btrim(coalesce(pr.first_name, '')), '') as first_name,
    coalesce(pr.newsletter_subscribed, true) as subscribed
  into v_profile
  from public.patients p
  join public.profiles pr on pr.user_id = p.user_id
  where p.id = new.patient_id
  limit 1;

  if v_profile.email is null or v_profile.email = '' or v_profile.subscribed is false then
    return new;
  end if;

  v_start := to_char(new.start_time at time zone 'America/Argentina/Buenos_Aires', 'DD/MM/YYYY HH24:MI');

  if new.start_time - interval '24 hours' > now() then
    insert into growth_os.email_jobs (
      job_type,
      recipient_email,
      recipient_name,
      user_id,
      patient_id,
      appointment_id,
      dedupe_key,
      scheduled_for,
      template_data
    )
    values (
      'appointment_reminder',
      v_profile.email,
      v_profile.first_name,
      v_profile.user_id,
      new.patient_id,
      new.id,
      'appointment_reminder:' || new.id::text || ':24h',
      new.start_time - interval '24 hours',
      jsonb_build_object(
        'appointment_time', v_start,
        'action_url', 'https://www.autamedica.com/patients/appointments?utm_source=email&utm_medium=reminder&utm_campaign=appointment_24h',
        'unsubscribe_url', 'https://www.autamedica.com/unsubscribe?user=' || coalesce(v_profile.user_id::text, v_profile.email)
      )
    )
    on conflict (dedupe_key) do nothing;
  end if;

  if new.start_time - interval '2 hours' > now() then
    insert into growth_os.email_jobs (
      job_type,
      recipient_email,
      recipient_name,
      user_id,
      patient_id,
      appointment_id,
      dedupe_key,
      scheduled_for,
      template_data
    )
    values (
      'appointment_reminder',
      v_profile.email,
      v_profile.first_name,
      v_profile.user_id,
      new.patient_id,
      new.id,
      'appointment_reminder:' || new.id::text || ':2h',
      new.start_time - interval '2 hours',
      jsonb_build_object(
        'appointment_time', v_start,
        'action_url', 'https://www.autamedica.com/patients/appointments?utm_source=email&utm_medium=reminder&utm_campaign=appointment_2h',
        'unsubscribe_url', 'https://www.autamedica.com/unsubscribe?user=' || coalesce(v_profile.user_id::text, v_profile.email)
      )
    )
    on conflict (dedupe_key) do nothing;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "growth_os"."enqueue_appointment_email_reminders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "growth_os"."enqueue_concierge_agent_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'growth_os', 'public'
    AS $$
declare
  target_channel text;
  job_key text;
begin
  if new.status in ('booked', 'paid', 'lost', 'unsubscribed') then
    return new;
  end if;

  if coalesce(new.consent_marketing, false) is not true then
    return new;
  end if;

  target_channel := case
    when nullif(btrim(coalesce(new.phone, '')), '') is not null
      then 'whatsapp_openclaw'
    else 'email_resend'
  end;

  job_key := concat_ws(
    ':',
    'agent',
    'concierge',
    new.id::text,
    coalesce(new.status, 'new'),
    coalesce(new.vertical, 'general')
  );

  insert into growth_os.agent_jobs (
    agent_type,
    trigger_type,
    source_table,
    source_id,
    lead_id,
    channel,
    payload,
    idempotency_key
  )
  values (
    'concierge',
    tg_op,
    'growth_os.leads',
    new.id::text,
    new.id,
    target_channel,
    jsonb_build_object(
      'lead_email', new.email,
      'lead_name', new.name,
      'vertical', new.vertical,
      'intent', new.intent,
      'status', new.status,
      'form_id', new.form_id,
      'metadata', new.metadata
    ),
    job_key
  )
  on conflict (idempotency_key) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "growth_os"."enqueue_concierge_agent_job"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "growth_os"."enqueue_doctor_anamnesis_ready"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'growth_os', 'public'
    AS $$
declare
  v_doctor_profile record;
  v_patient_profile record;
  v_appointment_id uuid;
  v_doctor_id uuid;
begin
  if new.status <> 'completed' or old.status = 'completed' then
    return new;
  end if;

  -- Find the next upcoming appointment for this patient
  select id, doctor_id
  into v_appointment_id, v_doctor_id
  from public.appointments
  where patient_id = new.patient_id
    and status in ('scheduled', 'confirmed')
    and start_time > now()
  order by start_time asc
  limit 1;

  if v_appointment_id is null then
    return new; -- No upcoming appointment, don't email any doctor
  end if;

  -- Get doctor details
  select pr.user_id, lower(pr.email) as email, nullif(btrim(coalesce(pr.first_name, '')), '') as first_name
  into v_doctor_profile
  from public.doctors d
  join public.profiles pr on pr.user_id = d.user_id
  where d.id = v_doctor_id
  limit 1;

  -- Get patient details
  select pr.user_id, nullif(btrim(coalesce(pr.first_name, '')), '') || ' ' || nullif(btrim(coalesce(pr.last_name, '')), '') as full_name
  into v_patient_profile
  from public.patients p
  join public.profiles pr on pr.user_id = p.user_id
  where p.id = new.patient_id
  limit 1;

  if v_doctor_profile.email is not null and v_doctor_profile.email <> '' then
    insert into growth_os.email_jobs (
      job_type, recipient_email, recipient_name, user_id, patient_id, dedupe_key, template_data
    ) values (
      'doctor_anamnesis_ready',
      v_doctor_profile.email,
      v_doctor_profile.first_name,
      v_doctor_profile.user_id,
      new.patient_id,
      'doctor_anamnesis:' || new.id::text || ':' || v_appointment_id::text,
      jsonb_build_object(
        'patient_name', trim(v_patient_profile.full_name),
        'action_url', 'https://www.autamedica.com/doctors/patients/' || new.patient_id::text || '/anamnesis'
      )
    ) on conflict (dedupe_key) do nothing;
  end if;

  return new;
end;
$$;


