    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'growth_os', 'public'
    AS $$
declare
  v_name text;
  v_user_key text;
begin
  if new.email is null or btrim(new.email) = '' then
    return new;
  end if;

  if coalesce(new.newsletter_subscribed, true) is false then
    return new;
