CREATE OR REPLACE FUNCTION "growth_os"."is_notification_contact_suppressed"("contact_channel" "text", "contact_value" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'growth_os', 'public'
    AS $$
  select exists (
    select 1
    from growth_os.suppressed_notification_contacts c
    where c.channel = contact_channel
      and c.contact_value = growth_os.normalize_notification_contact(contact_channel, contact_value)
  );
$$;


