CREATE OR REPLACE FUNCTION "growth_os"."touch_patient_activation_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.updated_at := now();
  
  -- Auto-compute days_to_activation when patient reaches 'activated'
  if new.current_step = 'activated' and new.acquired_at is not null then
    new.days_to_activation := extract(day from (now() - new.acquired_at))::int;
  end if;
  
  -- Auto-set churned_at when step changes to 'churned'
  if new.current_step = 'churned' and old.current_step != 'churned' then
    new.churned_at := coalesce(new.churned_at, now());
  end if;
  
  return new;
end;
$$;


