CREATE OR REPLACE FUNCTION "public"."assert_p2p_chat_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NEW.event_type <> 'message' OR NEW.channel <> 'text' THEN
        RETURN NEW;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.conversation_sessions s
        WHERE s.id = NEW.session_id
          AND s.patient_id = NEW.patient_id
          AND s.channel = 'chat'
          AND s.status = 'active'
          AND s.doctor_id IS NOT NULL
          AND s.workflow_type = 'p2p_chat'
    ) THEN
        RETURN NEW;
    END IF;

    IF NEW.role NOT IN ('patient', 'doctor') THEN
        RAISE EXCEPTION 'invalid_p2p_chat_role';
    END IF;

    IF NEW.role = 'doctor' AND NOT EXISTS (
        SELECT 1
        FROM public.conversation_sessions s
        JOIN public.doctors d ON d.id = s.doctor_id
        WHERE s.id = NEW.session_id
          AND d.user_id = auth.uid()
    ) THEN
        RAISE EXCEPTION 'doctor_not_allowed_for_chat';
    END IF;

    IF NEW.role = 'patient' AND NOT EXISTS (
        SELECT 1
        FROM public.patients p
        WHERE p.id = NEW.patient_id
          AND p.user_id = auth.uid()
    ) THEN
        RAISE EXCEPTION 'patient_not_allowed_for_chat';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."assert_p2p_chat_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_profile_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role THEN
    INSERT INTO public.auth_audit(user_id, event, data)
    VALUES (
      NEW.user_id,
      'role_changed',
      jsonb_build_object(
        'from', OLD.role,
        'to', NEW.role
      )
    );
  END IF;

  NEW.updated_at := now();

  RETURN NEW;
END;
$$;


