CREATE OR REPLACE FUNCTION "public"."can_access_p2p_chat_session"("target_session_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.conversation_sessions s
        JOIN public.patients p ON p.id = s.patient_id
        LEFT JOIN public.doctors d ON d.id = s.doctor_id
        WHERE s.id = target_session_id
          AND s.channel = 'chat'
          AND (
            p.user_id = auth.uid()
            OR (
                d.user_id = auth.uid()
                AND public.doctor_can_chat_with_patient(s.doctor_id, s.patient_id)
            )
          )
    );
$$;


