CREATE OR REPLACE FUNCTION "public"."doctor_has_patient_access"("patient_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_doctor_id uuid;
  v_patient_id uuid;
BEGIN
  -- Verificar que el usuario actual es doctor
  IF NOT public.is_doctor() THEN
    RETURN false;
  END IF;

  -- Obtener ID del doctor actual
  SELECT id INTO v_doctor_id
  FROM public.doctors
  WHERE user_id = auth.uid() AND active = true;

  -- Obtener ID del paciente
  SELECT id INTO v_patient_id
  FROM public.patients
  WHERE user_id = patient_user_id AND active = true;

  IF v_doctor_id IS NULL OR v_patient_id IS NULL THEN
    RETURN false;
  END IF;

  -- Verificar si existe relación en alguna de las 3 fuentes de verdad
  RETURN EXISTS (
    -- 1. Care Team (Relación formal)
    SELECT 1 FROM public.patient_care_team
    WHERE doctor_id = v_doctor_id AND patient_id = v_patient_id AND active = true
    UNION ALL
    -- 2. Doctor Patient (Relación automática por citas)
    SELECT 1 FROM public.doctor_patient
    WHERE doctor_id = v_doctor_id AND patient_id = v_patient_id
    UNION ALL
    -- 3. Appointments (Citas directas)
    SELECT 1 FROM public.appointments
    WHERE doctor_id = v_doctor_id AND patient_id = v_patient_id AND deleted_at IS NULL
  );
END;
$$;


ALTER FUNCTION "public"."doctor_has_patient_access"("patient_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."doctor_has_patient_access"("patient_user_id" "uuid") IS 'Verifica si un doctor tiene acceso autorizado a un paciente específico';



CREATE OR REPLACE FUNCTION "public"."enforce_bridge_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.prescription_type = 'transition_bridge'
     AND NEW.prescription_type = 'transition_bridge'
     AND (
       NEW.quantity_units IS DISTINCT FROM OLD.quantity_units
       OR NEW.formulation IS DISTINCT FROM OLD.formulation
       OR NEW.dose_mg_per_day IS DISTINCT FROM OLD.dose_mg_per_day
     )
     AND NEW.status NOT IN ('clarification_provided', 'cancelled')
  THEN
    RAISE EXCEPTION 'Bridge prescriptions cannot be modified without prescriber revalidation. '
      'Current status: %. Use clarification workflow to request changes.', NEW.status
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_bridge_immutability"() OWNER TO "postgres";


