CREATE OR REPLACE FUNCTION "public"."get_doctor_online_minutes"("p_doctor_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
    heartbeat_count integer;
BEGIN
    SELECT count(*)::integer INTO heartbeat_count
    FROM public.doctor_heartbeats
    WHERE doctor_id = p_doctor_id
      AND created_at BETWEEN p_start_date AND p_end_date;
      
    -- Asumimos latidos cada 5 minutos
    RETURN heartbeat_count * 5;
END;
$$;


