CREATE OR REPLACE FUNCTION "public"."get_or_create_p2p_chat_session"("target_patient_id" "uuid", "target_doctor_id" "uuid", "target_case_id" "text" DEFAULT 'general_followup'::"text") RETURNS "public"."conversation_sessions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    chat_session public.conversation_sessions;
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.patients p
        LEFT JOIN public.doctors d ON d.id = target_doctor_id
        WHERE p.id = target_patient_id
          AND (
            p.user_id = auth.uid()
            OR (
                d.user_id = auth.uid()
                AND public.doctor_can_chat_with_patient(target_doctor_id, target_patient_id)
            )
          )
    ) THEN
        RAISE EXCEPTION 'chat_participants_not_allowed';
    END IF;

    SELECT *
    INTO chat_session
    FROM public.conversation_sessions
    WHERE patient_id = target_patient_id
      AND doctor_id = target_doctor_id
      AND case_id = target_case_id
      AND workflow_type = 'p2p_chat'
      AND channel = 'chat'
      AND status = 'active'
    ORDER BY started_at DESC
    LIMIT 1;

    IF chat_session.id IS NOT NULL THEN
        RETURN chat_session;
    END IF;

    INSERT INTO public.conversation_sessions (
        patient_id,
        doctor_id,
        case_id,
        status,
        channel,
        workflow_type
    )
    VALUES (
        target_patient_id,
        target_doctor_id,
        target_case_id,
        'active',
        'chat',
        'p2p_chat'
    )
    RETURNING * INTO chat_session;

    RETURN chat_session;
END;
$$;


ALTER FUNCTION "public"."get_or_create_p2p_chat_session"("target_patient_id" "uuid", "target_doctor_id" "uuid", "target_case_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recommended_screenings"("patient_id_param" "uuid", "include_overdue" boolean DEFAULT true) RETURNS TABLE("screening_id" "uuid", "screening_name" "text", "category" "text", "status" "text", "next_due_date" timestamp with time zone, "urgency" "text", "reason" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  patient_age integer;
  patient_gender text;
BEGIN
  SELECT
    DATE_PART('year', AGE(birth_date)),
    gender
  INTO patient_age, patient_gender
  FROM public.patients
  WHERE id = patient_id_param;

  IF patient_age IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    s.id AS screening_id,
    s.name AS screening_name,
    s.category,
    COALESCE(pscr.status, 'not_started') AS status,
    pscr.next_due_date,
    CASE
      WHEN pscr.status = 'overdue' THEN 'high'::text
      WHEN pscr.next_due_date IS NOT NULL
        AND pscr.next_due_date <= NOW() + INTERVAL '30 days' THEN 'medium'::text
      ELSE 'low'::text
    END AS urgency,
    CASE
      WHEN pscr.status = 'overdue' THEN 'Screening vencido - requiere atención'
      WHEN s.is_mandatory THEN 'Screening obligatorio según normativa argentina'
      ELSE 'Recomendado para su edad y perfil'
    END AS reason
  FROM public.preventive_screenings s
  LEFT JOIN public.patient_screenings pscr
    ON pscr.screening_id = s.id
   AND pscr.patient_id = patient_id_param
  WHERE (s.target_gender = 'all' OR s.target_gender = patient_gender)
    AND (s.min_age IS NULL OR patient_age >= s.min_age)
    AND (s.max_age IS NULL OR patient_age <= s.max_age)
    AND (include_overdue = true OR COALESCE(pscr.status, 'not_started') != 'overdue')
  ORDER BY
    CASE
      WHEN pscr.status = 'overdue' THEN 1
      WHEN s.is_mandatory THEN 2
      ELSE 3
    END,
    pscr.next_due_date NULLS LAST,
    s.name;
END;
$$;


ALTER FUNCTION "public"."get_recommended_screenings"("patient_id_param" "uuid", "include_overdue" boolean) OWNER TO "postgres";


