CREATE OR REPLACE FUNCTION "public"."is_platform_or_org_admin"("p_uid" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  identifier_column text;
  v_current_role text;
BEGIN
  IF p_uid IS NULL THEN
    RETURN false;
  END IF;

  SELECT
    CASE
      WHEN EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = 'profiles'
          AND column_name = 'user_id'
      ) THEN 'user_id'
      WHEN EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = 'profiles'
          AND column_name = 'id'
      ) THEN 'id'
      ELSE NULL
    END
  INTO identifier_column;

  IF identifier_column IS NULL THEN
    RETURN false;
  END IF;

  EXECUTE format(
    'SELECT role::text FROM public.profiles WHERE %I = $1 LIMIT 1',
    identifier_column
  )
  INTO v_current_role
  USING p_uid;

  RETURN v_current_role IN ('platform_admin', 'organization_admin', 'admin');
END;
$_$;


