CREATE OR REPLACE FUNCTION "public"."log_appointment_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_action text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'created';
  ELSIF OLD.status IS DISTINCT FROM NEW.status THEN
    v_action := NEW.status;
  ELSIF OLD.start_time IS DISTINCT FROM NEW.start_time THEN
    v_action := 'rescheduled';
  ELSE
    v_action := 'updated';
  END IF;

  INSERT INTO public.appointment_history (
    appointment_id, patient_id, doctor_id, action, old_status, new_status, metadata
  ) VALUES (
    NEW.id,
    NEW.patient_id,
    NEW.doctor_id,
    v_action,
    CASE WHEN TG_OP = 'UPDATE' THEN OLD.status ELSE NULL END,
    NEW.status,
    jsonb_build_object(
      'trigger_op', TG_OP,
      'old_start_time', CASE WHEN TG_OP = 'UPDATE' THEN OLD.start_time::text ELSE NULL END,
      'new_start_time', NEW.start_time::text
    )
  );

  RETURN NEW;
END;
$$;


