CREATE OR REPLACE FUNCTION "public"."mark_overdue_appointments_no_show"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_marked integer := 0;
BEGIN
  WITH due AS (
    SELECT
      a.id
    FROM public.appointments a
    LEFT JOIN public.doctor_scheduling_config cfg
      ON cfg.doctor_id = a.doctor_id
    WHERE a.status IN ('scheduled', 'confirmed')
      AND COALESCE(
        a.end_time,
        a.start_time + (COALESCE(a.duration_minutes, 30) || ' minutes')::interval
      ) < now() - make_interval(mins => COALESCE(cfg.noshow_grace_minutes, 30))
  ),
  updated AS (
    UPDATE public.appointments a
    SET
      status = 'no_show',
      updated_at = now()
    FROM due
    WHERE a.id = due.id
    RETURNING a.id
  )
  SELECT count(*)::integer INTO v_marked FROM updated;

  RETURN v_marked;
END;
$$;


