CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_appointment_reminders"("target_appointment_id" "uuid", "reminder_channel" "text" DEFAULT 'whatsapp'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_appointment record;
  v_hours integer[];
  v_hour integer;
  v_reminder_time timestamptz;
  v_inserted integer := 0;
BEGIN
  SELECT id, doctor_id, start_time, status
  INTO v_appointment
  FROM public.appointments
  WHERE id = target_appointment_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'APPOINTMENT_NOT_FOUND: %', target_appointment_id;
  END IF;

  IF v_appointment.status IN ('cancelled', 'no_show', 'completed') THEN
    RETURN 0;
  END IF;

  SELECT reminder_hours_before
  INTO v_hours
  FROM public.doctor_scheduling_config
  WHERE doctor_id = v_appointment.doctor_id;

  v_hours := COALESCE(v_hours, ARRAY[24, 2]);

  FOREACH v_hour IN ARRAY v_hours LOOP
    v_reminder_time := v_appointment.start_time - make_interval(hours => v_hour);

    IF v_reminder_time > now() THEN
      INSERT INTO public.appointment_reminders (
        appointment_id,
        channel,
        scheduled_for
      )
      VALUES (
        v_appointment.id,
        reminder_channel,
        v_reminder_time
      )
      ON CONFLICT (appointment_id, channel, scheduled_for) DO NOTHING;

      IF FOUND THEN
        v_inserted := v_inserted + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN v_inserted;
END;
$$;


ALTER FUNCTION "public"."schedule_appointment_reminders"("target_appointment_id" "uuid", "reminder_channel" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."schedule_appointment_reminders"("target_appointment_id" "uuid", "reminder_channel" "text") IS 'Crea recordatorios futuros para una cita usando la configuración del doctor o el default global';



CREATE OR REPLACE FUNCTION "public"."select_primary_role_for_profile"("target_profile_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    selected_role TEXT;
BEGIN
    SELECT ur.role
    INTO selected_role
    FROM public.user_roles ur
    WHERE ur.profile_id = target_profile_id
      AND (ur.expires_at IS NULL OR ur.expires_at > NOW())
    ORDER BY CASE ur.role
        WHEN 'platform_admin' THEN 100
        WHEN 'admin' THEN 90
        WHEN 'organization_admin' THEN 80
        WHEN 'company_admin' THEN 75
        WHEN 'company' THEN 70
        WHEN 'doctor' THEN 60
        WHEN 'patient' THEN 50
        ELSE 0
    END DESC,
    ur.granted_at DESC
    LIMIT 1;

    RETURN COALESCE(selected_role, 'patient');
END;
$$;


ALTER FUNCTION "public"."select_primary_role_for_profile"("target_profile_id" "uuid") OWNER TO "postgres";


