CREATE OR REPLACE FUNCTION "public"."set_user_role"("p_role" "public"."user_role") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  -- Solo permitir setear rol si aún no tiene uno
  UPDATE public.profiles
    SET role = p_role,
        updated_at = NOW()
  WHERE user_id = v_uid
    AND role IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'role_already_set_or_profile_missing';
  END IF;

  -- Auto-provisionar fila específica por rol
  IF p_role = 'doctor' THEN
    INSERT INTO public.doctors (user_id) VALUES (v_uid) ON CONFLICT (user_id) DO NOTHING;
  ELSIF p_role = 'patient' THEN
    INSERT INTO public.patients (user_id) VALUES (v_uid) ON CONFLICT (user_id) DO NOTHING;
  END IF;
END;
$$;


ALTER FUNCTION "public"."set_user_role"("p_role" "public"."user_role") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_call_to_appointment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF NEW.appointment_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Call connected → appointment in_progress
  IF NEW.status = 'connected' AND OLD.status IS DISTINCT FROM 'connected' THEN
    UPDATE public.appointments
    SET status = 'in_progress', updated_at = now()
    WHERE id = NEW.appointment_id
      AND status IN ('scheduled', 'confirmed');
  END IF;

  -- Call ended → appointment completed
  IF NEW.status = 'ended' AND OLD.status IS DISTINCT FROM 'ended' THEN
    UPDATE public.appointments
    SET status = 'completed', updated_at = now()
    WHERE id = NEW.appointment_id
      AND status IN ('in_progress', 'scheduled', 'confirmed');
  END IF;

  -- Call declined/canceled → appointment cancelled
  -- Only if no other non-terminal calls exist for this appointment.
  -- This prevents premature cancellation when the doctor might retry.
  IF NEW.status IN ('declined', 'canceled') AND OLD.status IS DISTINCT FROM NEW.status THEN
    UPDATE public.appointments a
    SET status = 'cancelled', updated_at = now()
    WHERE a.id = NEW.appointment_id
      AND a.status IN ('scheduled', 'confirmed')
      AND NOT EXISTS (
        SELECT 1 FROM public.calls c
        WHERE c.appointment_id = a.id
          AND c.id != NEW.id
          AND c.status NOT IN ('declined', 'canceled', 'ended')
      );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_call_to_appointment"() OWNER TO "postgres";


