    "dni_verified_at" timestamp with time zone,
    "triaged_at" timestamp with time zone,
    "anamnesis_started_at" timestamp with time zone,
    "anamnesis_completed_at" timestamp with time zone,
    "appointment_booked_at" timestamp with time zone,
    "consultation_done_at" timestamp with time zone,
    "prescription_sent_at" timestamp with time zone,
    "activated_at" timestamp with time zone,
    "churned_at" timestamp with time zone,
    "churn_reason" "text",
    "days_to_activation" integer,
    "source_channel" "text" DEFAULT 'direct'::"text" NOT NULL,
    "source_detail" "text",
    "utm_source" "text",
    "utm_medium" "text",
    "utm_campaign" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "patient_activation_current_step_check" CHECK (("current_step" = ANY (ARRAY['acquired'::"text", 'whatsapp_linked'::"text", 'dni_verified'::"text", 'triaged'::"text", 'anamnesis_started'::"text", 'anamnesis_completed'::"text", 'appointment_booked'::"text", 'consultation_done'::"text", 'prescription_sent'::"text", 'activated'::"text", 'churned'::"text"]))),
    CONSTRAINT "patient_activation_source_channel_check" CHECK (("source_channel" = ANY (ARRAY['whatsapp'::"text", 'web_landing'::"text", 'web_direct'::"text", 'direct'::"text", 'email_nurturing'::"text", 'referral'::"text", 'social'::"text", 'ad_paid'::"text", 'partner'::"text", 'other'::"text"])))
);


ALTER TABLE "growth_os"."patient_activation" OWNER TO "postgres";


COMMENT ON TABLE "growth_os"."patient_activation" IS 'Tracker de activación de pacientes: desde adquisición hasta primera consulta completada. Reemplaza CSVs manuales de activación.';



CREATE OR REPLACE VIEW "growth_os"."activation_funnel" AS
 SELECT "source_channel",
    "count"(*) FILTER (WHERE ("current_step" = 'acquired'::"text")) AS "acquired",
    "count"(*) FILTER (WHERE ("current_step" = ANY (ARRAY['whatsapp_linked'::"text", 'dni_verified'::"text", 'triaged'::"text", 'anamnesis_started'::"text", 'anamnesis_completed'::"text", 'appointment_booked'::"text", 'consultation_done'::"text", 'prescription_sent'::"text", 'activated'::"text"]))) AS "linked",
    "count"(*) FILTER (WHERE ("current_step" = ANY (ARRAY['dni_verified'::"text", 'triaged'::"text", 'anamnesis_started'::"text", 'anamnesis_completed'::"text", 'appointment_booked'::"text", 'consultation_done'::"text", 'prescription_sent'::"text", 'activated'::"text"]))) AS "dni_ok",
    "count"(*) FILTER (WHERE ("current_step" = ANY (ARRAY['triaged'::"text", 'anamnesis_started'::"text", 'anamnesis_completed'::"text", 'appointment_booked'::"text", 'consultation_done'::"text", 'prescription_sent'::"text", 'activated'::"text"]))) AS "triaged",
    "count"(*) FILTER (WHERE ("current_step" = ANY (ARRAY['anamnesis_completed'::"text", 'appointment_booked'::"text", 'consultation_done'::"text", 'prescription_sent'::"text", 'activated'::"text"]))) AS "anamnesis_done",
    "count"(*) FILTER (WHERE ("current_step" = ANY (ARRAY['appointment_booked'::"text", 'consultation_done'::"text", 'prescription_sent'::"text", 'activated'::"text"]))) AS "booked",
    "count"(*) FILTER (WHERE ("current_step" = ANY (ARRAY['consultation_done'::"text", 'prescription_sent'::"text", 'activated'::"text"]))) AS "consulted",
    "count"(*) FILTER (WHERE ("current_step" = 'activated'::"text")) AS "activated",
    "count"(*) FILTER (WHERE ("current_step" = 'churned'::"text")) AS "churned",
    "avg"("days_to_activation") FILTER (WHERE ("days_to_activation" IS NOT NULL)) AS "avg_days_to_activation"
   FROM "growth_os"."patient_activation"
  GROUP BY "source_channel"
  ORDER BY ("count"(*) FILTER (WHERE ("current_step" = 'acquired'::"text"))) DESC;


ALTER VIEW "growth_os"."activation_funnel" OWNER TO "postgres";


COMMENT ON VIEW "growth_os"."activation_funnel" IS 'Visión agregada del funnel de activación por canal de adquisición.';



