    "weight_kg" numeric(5,2),
    "emergency_contact" "jsonb",
    "medical_history" "jsonb" DEFAULT '[]'::"jsonb",
    "allergies" "jsonb" DEFAULT '[]'::"jsonb",
    "medications" "jsonb" DEFAULT '[]'::"jsonb",
    "insurance_info" "jsonb",
