CREATE OR REPLACE VIEW "growth_os"."appointment_notification_risks" AS
 SELECT "a"."id" AS "appointment_id",
    "a"."status",
    "a"."start_time",
    "a"."doctor_id",
    "a"."patient_id",
    "dp"."user_id" AS "doctor_user_id",
    "pp"."user_id" AS "patient_user_id",
    "growth_os"."normalize_notification_contact"('email'::"text", "dpr"."email") AS "doctor_email",
    "growth_os"."normalize_notification_contact"('whatsapp'::"text", "dpr"."phone") AS "doctor_phone",
    "growth_os"."normalize_notification_contact"('whatsapp'::"text", "ppr"."phone") AS "patient_phone",
    (EXISTS ( SELECT 1
           FROM "growth_os"."email_jobs" "ej"
          WHERE (("ej"."appointment_id" = "a"."id") AND ("ej"."job_type" = 'doctor_new_appointment'::"text") AND ("ej"."status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'sent'::"text"]))))) AS "doctor_email_enqueued",
    (EXISTS ( SELECT 1
           FROM "public"."portal_notifications" "pn"
          WHERE (("pn"."user_id" = "dp"."user_id") AND ("pn"."dedupe_key" = ('event:appointment.payment_confirmed:'::"text" || ("a"."id")::"text"))))) AS "doctor_portal_notification_enqueued",
    (EXISTS ( SELECT 1
           FROM "growth_os"."doctor_whatsapp_jobs" "dwj"
          WHERE (("dwj"."appointment_id" = "a"."id") AND ("dwj"."status" = ANY (ARRAY['pending'::"text", 'sent'::"text"]))))) AS "doctor_whatsapp_enqueued",
    (EXISTS ( SELECT 1
           FROM "public"."appointment_reminders" "ar"
          WHERE (("ar"."appointment_id" = "a"."id") AND ("ar"."channel" = 'whatsapp'::"text") AND ("ar"."status" = ANY (ARRAY['pending'::"text", 'sent'::"text"]))))) AS "patient_whatsapp_reminder_enqueued",
    "array_remove"(ARRAY[
        CASE
            WHEN (COALESCE("growth_os"."normalize_notification_contact"('email'::"text", "dpr"."email"), ''::"text") = ''::"text") THEN 'doctor_email_missing'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN "growth_os"."is_notification_contact_suppressed"('email'::"text", "dpr"."email") THEN 'doctor_email_suppressed'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ((COALESCE("growth_os"."normalize_notification_contact"('email'::"text", "dpr"."email"), ''::"text") <> ''::"text") AND ("growth_os"."is_notification_contact_suppressed"('email'::"text", "dpr"."email") IS FALSE) AND (NOT (EXISTS ( SELECT 1
               FROM "growth_os"."email_jobs" "ej"
              WHERE (("ej"."appointment_id" = "a"."id") AND ("ej"."job_type" = 'doctor_new_appointment'::"text") AND ("ej"."status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'sent'::"text"]))))))) THEN 'doctor_email_job_missing'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("growth_os"."normalize_notification_contact"('whatsapp'::"text", "dpr"."phone"), ''::"text") = ''::"text") THEN 'doctor_whatsapp_missing'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN "growth_os"."is_notification_contact_suppressed"('whatsapp'::"text", "dpr"."phone") THEN 'doctor_whatsapp_suppressed'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("growth_os"."normalize_notification_contact"('whatsapp'::"text", "ppr"."phone"), ''::"text") = ''::"text") THEN 'patient_whatsapp_missing'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM "public"."portal_notifications" "pn"
              WHERE (("pn"."user_id" = "dp"."user_id") AND ("pn"."dedupe_key" = ('event:appointment.payment_confirmed:'::"text" || ("a"."id")::"text")))))) THEN 'doctor_portal_notification_missing'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM "growth_os"."doctor_whatsapp_jobs" "dwj"
              WHERE (("dwj"."appointment_id" = "a"."id") AND ("dwj"."status" = ANY (ARRAY['pending'::"text", 'sent'::"text"])))))) THEN 'doctor_whatsapp_job_missing'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM "public"."appointment_reminders" "ar"
              WHERE (("ar"."appointment_id" = "a"."id") AND ("ar"."channel" = 'whatsapp'::"text") AND ("ar"."status" = ANY (ARRAY['pending'::"text", 'sent'::"text"])))))) THEN 'patient_whatsapp_reminder_missing'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "risk_reasons",
        CASE
            WHEN ("a"."start_time" <= ("now"() + '02:00:00'::interval)) THEN 'p0'::"text"
            WHEN ("a"."start_time" <= ("now"() + '24:00:00'::interval)) THEN 'p1'::"text"
            ELSE 'p2'::"text"
        END AS "urgency"
   FROM (((("public"."appointments" "a"
     JOIN "public"."doctors" "dp" ON (("dp"."id" = "a"."doctor_id")))
     JOIN "public"."profiles" "dpr" ON (("dpr"."user_id" = "dp"."user_id")))
     LEFT JOIN "public"."patients" "pp" ON (("pp"."id" = "a"."patient_id")))
     LEFT JOIN "public"."profiles" "ppr" ON (("ppr"."user_id" = "pp"."user_id")))
  WHERE (("a"."status" = 'confirmed'::"text") AND ("a"."start_time" >= "now"()) AND ((COALESCE("growth_os"."normalize_notification_contact"('email'::"text", "dpr"."email"), ''::"text") = ''::"text") OR "growth_os"."is_notification_contact_suppressed"('email'::"text", "dpr"."email") OR ((COALESCE("growth_os"."normalize_notification_contact"('email'::"text", "dpr"."email"), ''::"text") <> ''::"text") AND (NOT (EXISTS ( SELECT 1
           FROM "growth_os"."email_jobs" "ej"
          WHERE (("ej"."appointment_id" = "a"."id") AND ("ej"."job_type" = 'doctor_new_appointment'::"text") AND ("ej"."status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'sent'::"text"]))))))) OR (COALESCE("growth_os"."normalize_notification_contact"('whatsapp'::"text", "dpr"."phone"), ''::"text") = ''::"text") OR "growth_os"."is_notification_contact_suppressed"('whatsapp'::"text", "dpr"."phone") OR (COALESCE("growth_os"."normalize_notification_contact"('whatsapp'::"text", "ppr"."phone"), ''::"text") = ''::"text") OR (NOT (EXISTS ( SELECT 1
           FROM "public"."portal_notifications" "pn"
          WHERE (("pn"."user_id" = "dp"."user_id") AND ("pn"."dedupe_key" = ('event:appointment.payment_confirmed:'::"text" || ("a"."id")::"text")))))) OR (NOT (EXISTS ( SELECT 1
           FROM "growth_os"."doctor_whatsapp_jobs" "dwj"
          WHERE (("dwj"."appointment_id" = "a"."id") AND ("dwj"."status" = ANY (ARRAY['pending'::"text", 'sent'::"text"])))))) OR (NOT (EXISTS ( SELECT 1
           FROM "public"."appointment_reminders" "ar"
          WHERE (("ar"."appointment_id" = "a"."id") AND ("ar"."channel" = 'whatsapp'::"text") AND ("ar"."status" = ANY (ARRAY['pending'::"text", 'sent'::"text"]))))))));


ALTER VIEW "growth_os"."appointment_notification_risks" OWNER TO "postgres";


COMMENT ON VIEW "growth_os"."appointment_notification_risks" IS 'Operational incident guardrail: confirmed upcoming appointments missing doctor portal, doctor WhatsApp, or patient WhatsApp reminder evidence.';



