CREATE OR REPLACE VIEW "growth_os"."daily_activation_cohort" AS
 SELECT ("date_trunc"('day'::"text", "acquired_at"))::"date" AS "cohort_date",
    "source_channel",
    "count"(*) AS "total_acquired",
    "count"(*) FILTER (WHERE ("current_step" = 'activated'::"text")) AS "activated",
    "count"(*) FILTER (WHERE ("current_step" = 'churned'::"text")) AS "churned",
    "round"(((("count"(*) FILTER (WHERE ("current_step" = 'activated'::"text")))::numeric / (NULLIF("count"(*), 0))::numeric) * (100)::numeric), 1) AS "activation_rate_pct"
   FROM "growth_os"."patient_activation"
  WHERE ("acquired_at" IS NOT NULL)
  GROUP BY (("date_trunc"('day'::"text", "acquired_at"))::"date"), "source_channel"
  ORDER BY (("date_trunc"('day'::"text", "acquired_at"))::"date") DESC, "source_channel";


