CREATE OR REPLACE VIEW "public"."analytics_appointments" AS
 SELECT "md5"(COALESCE(("patient_id")::"text", ("id")::"text")) AS "patient_key",
        CASE
            WHEN ("doctor_id" IS NULL) THEN NULL::"text"
            ELSE "md5"(("doctor_id")::"text")
        END AS "doctor_key",
    COALESCE("status", 'unknown'::"text") AS "appointment_status",
    COALESCE("type", 'unknown'::"text") AS "appointment_type",
    "duration_minutes",
    ("start_time")::"date" AS "appointment_date",
    (EXTRACT(hour FROM "start_time"))::integer AS "appointment_hour",
    (COALESCE("status", ''::"text") = ANY (ARRAY['no_show'::"text", 'missed'::"text", 'absent'::"text"])) AS "is_no_show",
    (COALESCE("status", ''::"text") = ANY (ARRAY['cancelled'::"text", 'canceled'::"text"])) AS "is_cancelled",
    (COALESCE("status", ''::"text") = ANY (ARRAY['completed'::"text", 'ended'::"text"])) AS "is_completed"
   FROM "public"."appointments" "a"
  WHERE ("deleted_at" IS NULL);


ALTER VIEW "public"."analytics_appointments" OWNER TO "postgres";


