CREATE OR REPLACE VIEW "public"."analytics_clinical_triage_cases" AS
 SELECT "md5"(("patient_id")::"text") AS "patient_key",
    "workflow_type",
    "clinical_vertical",
    "case_intent",
    "triage_priority",
    "triage_priority_rank",
    "triage_status",
    COALESCE("requires_same_day_action", false) AS "requires_same_day_action",
    COALESCE("risk_of_interruption", 'unknown'::"text") AS "risk_of_interruption",
    "integrity_score",
    "integrity_status",
    "missing_field_count",
    "conflicted_field_count",
    "locked_field_count",
    ("assigned_doctor_id" IS NOT NULL) AS "has_assigned_doctor",
    ("created_at")::"date" AS "case_created_date",
    ("updated_at")::"date" AS "case_updated_date",
    ("resolution_deadline_at")::"date" AS "resolution_deadline_date",
    ("resolved_at")::"date" AS "resolved_date"
   FROM "public"."clinical_case_states" "ccs";


