CREATE OR REPLACE VIEW "public"."analytics_patient_data_quality" AS
 SELECT "md5"(("p"."id")::"text") AS "patient_key",
    "p"."organization_id",
        CASE
            WHEN ("p"."birth_date" IS NULL) THEN 'unknown'::"text"
            WHEN ("date_part"('year'::"text", "age"(("p"."birth_date")::timestamp with time zone)) < (18)::double precision) THEN 'under_18'::"text"
            WHEN (("date_part"('year'::"text", "age"(("p"."birth_date")::timestamp with time zone)) >= (18)::double precision) AND ("date_part"('year'::"text", "age"(("p"."birth_date")::timestamp with time zone)) <= (29)::double precision)) THEN '18_29'::"text"
            WHEN (("date_part"('year'::"text", "age"(("p"."birth_date")::timestamp with time zone)) >= (30)::double precision) AND ("date_part"('year'::"text", "age"(("p"."birth_date")::timestamp with time zone)) <= (44)::double precision)) THEN '30_44'::"text"
            WHEN (("date_part"('year'::"text", "age"(("p"."birth_date")::timestamp with time zone)) >= (45)::double precision) AND ("date_part"('year'::"text", "age"(("p"."birth_date")::timestamp with time zone)) <= (64)::double precision)) THEN '45_64'::"text"
            ELSE '65_plus'::"text"
        END AS "age_band",
    ("p"."gender" IS NOT NULL) AS "has_gender",
    ("p"."birth_date" IS NOT NULL) AS "has_birth_date",
    (("pr"."phone" IS NOT NULL) AND ("btrim"("pr"."phone") <> ''::"text")) AS "has_phone",
    ("p"."insurance_info" IS NOT NULL) AS "has_insurance_info",
    (((
        CASE
            WHEN ("p"."gender" IS NULL) THEN 1
            ELSE 0
        END +
        CASE
            WHEN ("p"."birth_date" IS NULL) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (("pr"."phone" IS NULL) OR ("btrim"("pr"."phone") = ''::"text")) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN ("p"."insurance_info" IS NULL) THEN 1
            ELSE 0
        END) AS "missing_demographic_field_count",
    4 AS "expected_demographic_field_count",
    ("p"."created_at")::"date" AS "patient_created_date"
   FROM ("public"."patients" "p"
     LEFT JOIN "public"."profiles" "pr" ON (("pr"."user_id" = "p"."user_id")))
  WHERE (COALESCE("p"."active", true) = true);


ALTER VIEW "public"."analytics_patient_data_quality" OWNER TO "postgres";


