CREATE MATERIALIZED VIEW "public"."clinical_gold_seasonal_metrics" AS
 SELECT "season",
    "symptom_name",
    "snomed_code",
    "icd11_code",
    "count"(*) AS "case_count"
   FROM ( SELECT "clinical_symptom_observations"."symptom_name",
            "clinical_symptom_observations"."snomed_code",
            "clinical_symptom_observations"."icd11_code",
                CASE
                    WHEN (((EXTRACT(month FROM "clinical_symptom_observations"."created_at") = (12)::numeric) AND (EXTRACT(day FROM "clinical_symptom_observations"."created_at") >= (21)::numeric)) OR (EXTRACT(month FROM "clinical_symptom_observations"."created_at") = ANY (ARRAY[(1)::numeric, (2)::numeric])) OR ((EXTRACT(month FROM "clinical_symptom_observations"."created_at") = (3)::numeric) AND (EXTRACT(day FROM "clinical_symptom_observations"."created_at") <= (20)::numeric))) THEN 'Verano'::"text"
                    WHEN (((EXTRACT(month FROM "clinical_symptom_observations"."created_at") = (3)::numeric) AND (EXTRACT(day FROM "clinical_symptom_observations"."created_at") >= (21)::numeric)) OR (EXTRACT(month FROM "clinical_symptom_observations"."created_at") = ANY (ARRAY[(4)::numeric, (5)::numeric])) OR ((EXTRACT(month FROM "clinical_symptom_observations"."created_at") = (6)::numeric) AND (EXTRACT(day FROM "clinical_symptom_observations"."created_at") <= (20)::numeric))) THEN 'Otoño'::"text"
                    WHEN (((EXTRACT(month FROM "clinical_symptom_observations"."created_at") = (6)::numeric) AND (EXTRACT(day FROM "clinical_symptom_observations"."created_at") >= (21)::numeric)) OR (EXTRACT(month FROM "clinical_symptom_observations"."created_at") = ANY (ARRAY[(7)::numeric, (8)::numeric])) OR ((EXTRACT(month FROM "clinical_symptom_observations"."created_at") = (9)::numeric) AND (EXTRACT(day FROM "clinical_symptom_observations"."created_at") <= (20)::numeric))) THEN 'Invierno'::"text"
                    ELSE 'Primavera'::"text"
                END AS "season"
           FROM "public"."clinical_symptom_observations"
          WHERE ("clinical_symptom_observations"."is_red_flag" = false)) "raw_seasons"
  GROUP BY "season", "symptom_name", "snomed_code", "icd11_code"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."clinical_gold_seasonal_metrics" OWNER TO "postgres";


