CREATE TABLE IF NOT EXISTS "public"."dispensation_orders" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prescription_id" "uuid" NOT NULL,
    "patient_id" "uuid" NOT NULL,
    "doctor_id" "uuid" NOT NULL,
    "pharmacy_id" "uuid",
    "prescription_type" "text" DEFAULT 'standard'::"text" NOT NULL,
    "medication" "text" NOT NULL,
    "formulation" "text" NOT NULL,
    "dose_mg_per_day" numeric(10,2),
    "quantity_units" integer NOT NULL,
    "duration_days" integer NOT NULL,
    "clinician_decision" "text" DEFAULT 'approved'::"text" NOT NULL,
    "requires_clarification" boolean DEFAULT false NOT NULL,
    "extraordinary_dose_flag" boolean DEFAULT false NOT NULL,
