    CONSTRAINT "dispensation_orders_clinician_decision_check" CHECK (("clinician_decision" = ANY (ARRAY['approved'::"text", 'conditional'::"text", 'under_review'::"text"]))),
    CONSTRAINT "dispensation_orders_dispense_mode_check" CHECK (("dispense_mode" = ANY (ARRAY['pickup'::"text", 'shipping'::"text"]))),
    CONSTRAINT "dispensation_orders_duration_days_check" CHECK (("duration_days" > 0)),
    CONSTRAINT "dispensation_orders_prescription_type_check" CHECK (("prescription_type" = ANY (ARRAY['standard'::"text", 'transition_bridge'::"text", 'continuation'::"text", 'emergency'::"text"]))),
    CONSTRAINT "dispensation_orders_quantity_units_check" CHECK (("quantity_units" > 0)),
    CONSTRAINT "dispensation_orders_reconciliation_status_check" CHECK (("reconciliation_status" = ANY (ARRAY['reconciled'::"text", 'partial'::"text", 'pending'::"text", 'conflict'::"text"]))),
    CONSTRAINT "dispensation_orders_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'assigned'::"text", 'under_review'::"text", 'clarification_requested'::"text", 'clarification_provided'::"text", 'approved_for_dispensation'::"text", 'dispensed'::"text", 'partially_dispensed'::"text", 'blocked'::"text", 'cancelled'::"text", 'expired'::"text"]))),
    CONSTRAINT "dispense_window_valid" CHECK (("dispense_window_end" >= "dispense_window_start"))
);


