    CONSTRAINT "user_roles_role_check" CHECK (("role" = ANY (ARRAY['patient'::"text", 'doctor'::"text", 'company'::"text", 'company_admin'::"text", 'organization_admin'::"text", 'admin'::"text", 'platform_admin'::"text"])))
);


ALTER TABLE "public"."user_roles" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_db_health" WITH ("security_invoker"='true') AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "pg_tables"
          WHERE ("pg_tables"."schemaname" = 'public'::"name")) AS "public_tables",
    ( SELECT "count"(*) AS "count"
           FROM "pg_tables" "t"
          WHERE (("t"."schemaname" = 'public'::"name") AND ("t"."tablename" <> 'spatial_ref_sys'::"name") AND (EXISTS ( SELECT 1
                   FROM "pg_class" "c"
                  WHERE (("c"."relname" = "t"."tablename") AND ("c"."relrowsecurity" = true)))))) AS "tables_with_rls",
    ( SELECT "count"(*) AS "count"
           FROM "pg_policies"
          WHERE ("pg_policies"."schemaname" = 'public'::"name")) AS "total_policies",
    ( SELECT "count"(*) AS "count"
           FROM "storage"."buckets") AS "storage_buckets",
    ( SELECT "count"(*) AS "count"
           FROM "public"."audit_logs"
          WHERE ("audit_logs"."created_at" > ("now"() - '24:00:00'::interval))) AS "audit_entries_24h",
    "now"() AS "checked_at";


ALTER VIEW "public"."v_db_health" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_db_health" IS 'DB health dashboard — no auth.users exposure, security_invoker=true';



CREATE OR REPLACE VIEW "public"."v_patient_demographics" AS
 WITH "patient_ages" AS (
         SELECT "patients"."id",
            "patients"."gender",
            "patients"."birth_date",
            (EXTRACT(year FROM "age"(("patients"."birth_date")::timestamp with time zone)))::integer AS "age",
            "patients"."address",
            "patients"."insurance_info"
           FROM "public"."patients"
          WHERE ("patients"."active" = true)
        ), "age_groups" AS (
         SELECT "patient_ages"."gender",
                CASE
                    WHEN ("patient_ages"."age" IS NULL) THEN 'Desconocido'::"text"
                    WHEN ("patient_ages"."age" < 18) THEN 'Menores de 18'::"text"
                    WHEN (("patient_ages"."age" >= 18) AND ("patient_ages"."age" <= 29)) THEN '18 a 29'::"text"
                    WHEN (("patient_ages"."age" >= 30) AND ("patient_ages"."age" <= 49)) THEN '30 a 49'::"text"
                    WHEN (("patient_ages"."age" >= 50) AND ("patient_ages"."age" <= 69)) THEN '50 a 69'::"text"
                    ELSE '70 o más'::"text"
                END AS "age_group",
                CASE
                    WHEN (("lower"("patient_ages"."address") ~~ '%lima%'::"text") OR ("lower"("patient_ages"."address") ~~ '%callao%'::"text") OR ("lower"("patient_ages"."address") ~~ '%cusco%'::"text") OR ("lower"("patient_ages"."address") ~~ '%cuzco%'::"text") OR ("lower"("patient_ages"."address") ~~ '%libertad%'::"text") OR ("lower"("patient_ages"."address") ~~ '%peru%'::"text") OR ("lower"("patient_ages"."address") ~~ '%perú%'::"text")) THEN 'Perú'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%miami%'::"text") OR ("lower"("patient_ages"."address") ~~ '%florida%'::"text") OR ("lower"("patient_ages"."address") ~~ '%usa%'::"text") OR ("lower"("patient_ages"."address") ~~ '%eeuu%'::"text") OR ("lower"("patient_ages"."address") ~~ '%fl,%'::"text")) THEN 'EEUU'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%chile%'::"text") OR ("lower"("patient_ages"."address") ~~ '%santiago de chile%'::"text") OR ("lower"("patient_ages"."address") ~~ '%región metropolitana%'::"text")) THEN 'Chile'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%uruguay%'::"text") OR ("lower"("patient_ages"."address") ~~ '%montevideo%'::"text") OR ("lower"("patient_ages"."address") ~~ '%maldonado%'::"text") OR ("lower"("patient_ages"."address") ~~ '%ciudad de la costa%'::"text") OR ("lower"("patient_ages"."address") ~~ '%canelones%'::"text")) THEN 'Uruguay'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%mexico%'::"text") OR ("lower"("patient_ages"."address") ~~ '%méxico%'::"text") OR ("lower"("patient_ages"."address") ~~ '%cancun%'::"text") OR ("lower"("patient_ages"."address") ~~ '%cancún%'::"text") OR ("lower"("patient_ages"."address") ~~ '%q.r.%'::"text")) THEN 'México'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%brazil%'::"text") OR ("lower"("patient_ages"."address") ~~ '%brasil%'::"text") OR ("lower"("patient_ages"."address") ~~ '%florianópolis%'::"text") OR ("lower"("patient_ages"."address") ~~ '%cumbuco%'::"text")) THEN 'Brasil'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%colombia%'::"text") OR ("lower"("patient_ages"."address") ~~ '%bogota%'::"text") OR ("lower"("patient_ages"."address") ~~ '%bogotá%'::"text") OR ("lower"("patient_ages"."address") ~~ '%pereira%'::"text") OR ("lower"("patient_ages"."address") ~~ '%risaralda%'::"text")) THEN 'Colombia'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%caba%'::"text") OR ("lower"("patient_ages"."address") ~~ '%capital federal%'::"text")) THEN 'CABA'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%buenos aires%'::"text") OR ("lower"("patient_ages"."address") ~~ '%provincia de buenos aires%'::"text") OR ("lower"("patient_ages"."address") ~~ '%gba%'::"text") OR ("lower"("patient_ages"."address") ~~ '%san martín%'::"text") OR ("lower"("patient_ages"."address") ~~ '%mar del plata%'::"text") OR ("lower"("patient_ages"."address") ~~ '%monte grande%'::"text")) THEN 'Buenos Aires'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%mendoza%'::"text") OR ("lower"("patient_ages"."address") ~~ '%vistalba%'::"text") OR ("lower"("patient_ages"."address") ~~ '%chacras de coria%'::"text")) THEN 'Mendoza'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%río negro%'::"text") OR ("lower"("patient_ages"."address") ~~ '%rio negro%'::"text") OR ("lower"("patient_ages"."address") ~~ '%bariloche%'::"text")) THEN 'Río Negro'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%córdoba%'::"text") OR ("lower"("patient_ages"."address") ~~ '%cordoba%'::"text") OR ("lower"("patient_ages"."address") ~~ '%mendiolaza%'::"text")) THEN 'Córdoba'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%santa fe%'::"text") OR ("lower"("patient_ages"."address") ~~ '%rosario%'::"text")) THEN 'Santa Fe'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%salta%'::"text") OR ("lower"("patient_ages"."address") ~~ '%quijano%'::"text")) THEN 'Salta'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%neuquén%'::"text") OR ("lower"("patient_ages"."address") ~~ '%neuquen%'::"text") OR ("lower"("patient_ages"."address") ~~ '%plottier%'::"text")) THEN 'Neuquén'::"text"
                    WHEN ("lower"("patient_ages"."address") ~~ '%san juan%'::"text") THEN 'San Juan'::"text"
                    WHEN ("lower"("patient_ages"."address") ~~ '%jujuy%'::"text") THEN 'Jujuy'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%santa cruz%'::"text") OR ("lower"("patient_ages"."address") ~~ '%calafate%'::"text") OR ("lower"("patient_ages"."address") ~~ '%olivia%'::"text")) THEN 'Santa Cruz'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%tucumán%'::"text") OR ("lower"("patient_ages"."address") ~~ '%tucuman%'::"text")) THEN 'Tucumán'::"text"
                    WHEN (("lower"("patient_ages"."address") ~~ '%tierra del fuego%'::"text") OR ("lower"("patient_ages"."address") ~~ '%ushuaia%'::"text")) THEN 'Tierra del Fuego'::"text"
                    WHEN ("lower"("patient_ages"."address") ~~ '%catamarca%'::"text") THEN 'Catamarca'::"text"
                    WHEN (("patient_ages"."address" IS NULL) OR ("patient_ages"."address" = ''::"text") OR ("patient_ages"."address" = 'Sin especificar'::"text")) THEN 'Sin especificar'::"text"
                    ELSE 'Otras provincias'::"text"
                END AS "region",
                CASE
                    WHEN (("patient_ages"."insurance_info" ->> 'name'::"text") IS NOT NULL) THEN ("patient_ages"."insurance_info" ->> 'name'::"text")
                    WHEN (("patient_ages"."insurance_info" ->> 'obra_social'::"text") IS NOT NULL) THEN ("patient_ages"."insurance_info" ->> 'obra_social'::"text")
                    WHEN (("patient_ages"."insurance_info" ->> 'plan'::"text") IS NOT NULL) THEN ("patient_ages"."insurance_info" ->> 'plan'::"text")
                    ELSE 'Particular / Sin Obra Social'::"text"
                END AS "insurance_name"
           FROM "patient_ages"
        )
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."patients"
          WHERE ("patients"."active" = true)) AS "total_active_patients",
    COALESCE("gender", 'prefer_not_to_say'::"text") AS "gender",
    "age_group",
    "region",
    "insurance_name",
    "count"(*) AS "count"
   FROM "age_groups"
  GROUP BY "gender", "age_group", "region", "insurance_name";


ALTER VIEW "public"."v_patient_demographics" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_patient_demographics" IS 'Vista agregada en tiempo real para demografía de pacientes sin exponer datos personales.';



CREATE TABLE IF NOT EXISTS "public"."vital_signs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "patient_id" "uuid" NOT NULL,
    "recorded_by_id" "uuid",
    "type" "text" DEFAULT 'blood_pressure'::"text" NOT NULL,
    "blood_pressure_systolic" smallint,
    "blood_pressure_diastolic" smallint,
    "heart_rate" smallint,
    "temperature" numeric(4,1),
    "oxygen_saturation" smallint,
    "respiratory_rate" smallint,
    "weight" numeric(5,2),
    "height" smallint,
    "bmi" numeric(5,2),
    "pain_scale" smallint,
    "unit" "text",
    "notes" "text",
    "measurement_context" "text" DEFAULT 'patient_self_report'::"text" NOT NULL,
    "measured_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "recorded_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "vital_signs_bmi_range" CHECK ((("bmi" IS NULL) OR (("bmi" >= (5)::numeric) AND ("bmi" <= (100)::numeric)))),
    CONSTRAINT "vital_signs_bp_required" CHECK ((("type" <> 'blood_pressure'::"text") OR (("blood_pressure_systolic" IS NOT NULL) AND ("blood_pressure_diastolic" IS NOT NULL)))),
    CONSTRAINT "vital_signs_diastolic_range" CHECK ((("blood_pressure_diastolic" IS NULL) OR (("blood_pressure_diastolic" >= 20) AND ("blood_pressure_diastolic" <= 200)))),
    CONSTRAINT "vital_signs_heart_rate_range" CHECK ((("heart_rate" IS NULL) OR (("heart_rate" >= 20) AND ("heart_rate" <= 260)))),
    CONSTRAINT "vital_signs_height_range" CHECK ((("height" IS NULL) OR (("height" >= 30) AND ("height" <= 280)))),
    CONSTRAINT "vital_signs_oxygen_range" CHECK ((("oxygen_saturation" IS NULL) OR (("oxygen_saturation" >= 50) AND ("oxygen_saturation" <= 100)))),
    CONSTRAINT "vital_signs_pain_scale_range" CHECK ((("pain_scale" IS NULL) OR (("pain_scale" >= 0) AND ("pain_scale" <= 10)))),
    CONSTRAINT "vital_signs_respiratory_range" CHECK ((("respiratory_rate" IS NULL) OR (("respiratory_rate" >= 5) AND ("respiratory_rate" <= 80)))),
    CONSTRAINT "vital_signs_systolic_range" CHECK ((("blood_pressure_systolic" IS NULL) OR (("blood_pressure_systolic" >= 40) AND ("blood_pressure_systolic" <= 300)))),
    CONSTRAINT "vital_signs_temperature_range" CHECK ((("temperature" IS NULL) OR (("temperature" >= 30.0) AND ("temperature" <= 45.0)))),
    CONSTRAINT "vital_signs_type_check" CHECK (("type" = ANY (ARRAY['blood_pressure'::"text", 'heart_rate'::"text", 'temperature'::"text", 'oxygen_saturation'::"text", 'respiratory_rate'::"text", 'weight'::"text", 'height'::"text", 'pain_scale'::"text", 'composite'::"text"]))),
    CONSTRAINT "vital_signs_weight_range" CHECK ((("weight" IS NULL) OR (("weight" >= (1)::numeric) AND ("weight" <= (500)::numeric))))
);


