CREATE POLICY "Doctors can insert assigned chat sessions" ON "public"."conversation_sessions" FOR INSERT WITH CHECK ((("channel" = 'chat'::"text") AND (EXISTS ( SELECT 1
   FROM "public"."doctors" "d"
  WHERE (("d"."id" = "conversation_sessions"."doctor_id") AND ("d"."user_id" = "auth"."uid"())))) AND "public"."doctor_can_chat_with_patient"("doctor_id", "patient_id")));



CREATE POLICY "Doctors can insert chat messages" ON "public"."conversation_events" FOR INSERT WITH CHECK ((("role" = 'doctor'::"text") AND "public"."can_access_p2p_chat_session"("session_id") AND (EXISTS ( SELECT 1
   FROM "public"."conversation_sessions" "s"
  WHERE (("s"."id" = "conversation_events"."session_id") AND ("s"."patient_id" = "conversation_events"."patient_id"))))));



