CREATE POLICY "symptom_reports_select_scoped" ON "public"."symptom_reports" FOR SELECT TO "authenticated" USING ((("deleted_at" IS NULL) AND ((EXISTS ( SELECT 1
   FROM ("public"."doctor_patient" "dp"
     JOIN "public"."doctors" "d" ON (("d"."id" = "dp"."doctor_id")))
  WHERE (("d"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("dp"."patient_id" = "symptom_reports"."patient_id")))) OR ("patient_id" IN ( SELECT "patients"."id"
   FROM "public"."patients"
  WHERE ("patients"."user_id" = ( SELECT "auth"."uid"() AS "uid")))))));



CREATE POLICY "system_insert_audit" ON "public"."auth_audit" FOR INSERT TO "authenticated", "service_role" WITH CHECK (((( SELECT "auth"."uid"() AS "uid") IS NOT NULL) OR (( SELECT "auth"."role"() AS "role") = 'service_role'::"text")));



