   FROM "public"."patients" "p"
  WHERE (("p"."id" = "telemedicine_sessions"."patient_id") AND ("p"."user_id" = ( SELECT "auth"."uid"() AS "uid")))))));



CREATE POLICY "telemedicine_sessions_update_participants" ON "public"."telemedicine_sessions" FOR UPDATE USING ((("patient_id" = ( SELECT "auth"."uid"() AS "uid")) OR ("doctor_id" = ( SELECT "auth"."uid"() AS "uid")) OR (EXISTS ( SELECT 1
   FROM "public"."doctors" "d"
  WHERE (("d"."id" = "telemedicine_sessions"."doctor_id") AND ("d"."user_id" = ( SELECT "auth"."uid"() AS "uid"))))) OR (EXISTS ( SELECT 1
   FROM "public"."patients" "p"
  WHERE (("p"."id" = "telemedicine_sessions"."patient_id") AND ("p"."user_id" = ( SELECT "auth"."uid"() AS "uid"))))))) WITH CHECK ((("patient_id" = ( SELECT "auth"."uid"() AS "uid")) OR ("doctor_id" = ( SELECT "auth"."uid"() AS "uid")) OR (EXISTS ( SELECT 1
   FROM "public"."doctors" "d"
  WHERE (("d"."id" = "telemedicine_sessions"."doctor_id") AND ("d"."user_id" = ( SELECT "auth"."uid"() AS "uid"))))) OR (EXISTS ( SELECT 1
